// ============================================================
// FR&R TEST DATA — q: question, o: [options a-d], a: correct index,
// r: rationale, ref: chapter + enabling objective.
// Source: FR&R Practice Tests 1-3 (NAVAVSCOLSCOM-SG-200 Unit 5,
// Trainee Guide Q-9B-0178, 08NOV24), incl. their answer keys & reasoning.
// ============================================================
const TESTS = [
{
  name: "Test 1 \u2014 Easy",
  desc: "Single-concept recall drawn directly from Student Guide language.",
  questions: [
    {q:"What organization is responsible for establishing, reviewing, and enforcing the general regulations for all aviation activities in the United States?", o:["Department of Defense", "Chief of Naval Air Forces", "Federal Aviation Administration", "International Civil Aviation Organization"], a:2, r:"FAA. IS 5-1-2: \"The Federal Aviation Administration (FAA) is responsible for establishing, reviewing, and enforcing general regulations for all aviation activities in the United States.\"", ref:"Ch 5-1, EO 2.132"},
    {q:"Which section of the Federal Aviation Regulations most affects Naval Aviators?", o:["FAR Part 61", "FAR Part 91", "FAR Part 121", "FAR Part 141"], a:1, r:"FAR Part 91. \"The section of the FAR which most affects Naval Aviators is FAR Part 91 entitled 'General Operating and Flight Rules.'\"", ref:"Ch 5-1, EO 2.132"},
    {q:"Which organization publishes the Aeronautical Information Manual (AIM)?", o:["FAA", "DoD", "CNAF", "NAVAIR"], a:0, r:"FAA. \"The AIM is published by the FAA as an official guide to basic flight information and Air Traffic Control procedures.\" Common trap: the AIM is not a DoD product.", ref:"Ch 5-1, EO 2.132"},
    {q:"Which of the following best describes the AIM?", o:["A regulatory publication that supersedes FAR Part 91", "A non-regulatory publication that is consistent with FAR Part 91", "A DoD publication containing approach plates", "A Navy instruction governing aircraft operations worldwide"], a:1, r:"Non-regulatory, consistent with FAR Part 91. The guide notes explicitly: \"The AIM is a non-regulatory publication,\" and while wording may differ, the information is consistent with Part 91.", ref:"Ch 5-1, EO 2.133"},
    {q:"Which publication is published by the Department of Defense for use by all branches of the military?", o:["FAR Part 91", "Aeronautical Information Manual", "Flight Information Publications (FLIPs)", "CNAF M-3710.7"], a:2, r:"FLIPs. \"The Department of Defense (DoD) publishes these manuals for use by all branches of the military.\" FLIPs include en route charts, supplements, approach plates, general planning and area planning.", ref:"Ch 5-1, EO 2.134"},
    {q:"As a Student Naval Aviator flying a T-6, which publication's procedures take priority over all others?", o:["FLIPs", "FAR Part 91", "CNAF M-3710.7", "T-6 NATOPS Flight Manual"], a:3, r:"T-6 NATOPS. Priority of regulations: (1) NATOPS Flight Manual, (2) CNAF M-3710.7, (3) FLIPs, (4) FAR Part 91. Aircraft-specific NATOPS is always on top.", ref:"Ch 5-1, EO 2.134"},
    {q:"According to CNAF M-3710.7, which publication has the LOWEST priority for regulation compliance?", o:["Aircraft NATOPS Flight Manual", "CNAF M-3710.7", "FLIPs", "FAR Part 91"], a:3, r:"FAR Part 91. It is #4 of 4 in the priority list, and per Figure 1-5 applies only within U.S. airspace.", ref:"Ch 5-1, EO 2.134"},
    {q:"In NATOPS terminology, the word \"shall\" means that a procedure is:", o:["Recommended", "Optional", "Mandatory", "Anticipated in the future"], a:2, r:"Mandatory. NATOPS wording: shall = mandatory.", ref:"Ch 5-1, EO 2.135"},
    {q:"In NATOPS terminology, the word \"should\" means that a procedure is:", o:["Mandatory", "Recommended", "Optional", "Prohibited"], a:1, r:"Recommended. NATOPS wording: should = recommended.", ref:"Ch 5-1, EO 2.135"},
    {q:"Which ATC sub-agency provides pilot briefings, en route communications, some search and rescue services, and originates NOTAMs?", o:["Control Tower", "Clearance Delivery", "Flight Service Station", "ARTCC"], a:2, r:"Flight Service Station. FSS provides pilot briefings, en route communications, some SAR, relays ATC clearances, originates NOTAMs, broadcasts weather, and receives/processes flight plans.", ref:"Ch 5-1, EO 2.136"},
    {q:"Which ATC facility is the sole source of clearance to take off and to land?", o:["Ground", "Clearance Delivery", "Tower", "Approach Control"], a:2, r:"Tower. \"Tower is the sole source of clearance to take off and to land.\" Ground does not clear aircraft onto the active runway.", ref:"Ch 5-1, EO 2.136"},
    {q:"The primary function of Approach Control and Departure Control is to control:", o:["VFR traffic on the airport surface", "IFR traffic in the terminal area", "En route IFR traffic between terminal areas", "All traffic within Class G airspace"], a:1, r:"IFR traffic in the terminal area. \"The primary function of Approach Control and Departure Control is to control Instrument Flight Rules (IFR) traffic in the terminal area.\"", ref:"Ch 5-1, EO 2.136"},
    {q:"Which ATC facility is established primarily to control en route IFR traffic between terminal areas?", o:["TRACON", "ARTCC", "FSS", "Control Tower"], a:1, r:"ARTCC. \"Center is established primarily to control en route IFR traffic, i.e., IFR traffic that is between terminal areas.\"", ref:"Ch 5-1, EO 2.136"},
    {q:"As Pilot in Command, you are responsible for which of the following?", o:["Operation and safety of the aircraft", "Safe and orderly conduct of the flight", "Well-being of the crew", "All of the above"], a:3, r:"All of the above. Combining the FAR definition (operation and safety of the aircraft) and the CNAF definition (safe, orderly flight and well-being of the crew). Matches Assignment Sheet 5-1-3 Q7.", ref:"Ch 5-1, EO 2.137"},
    {q:"According to CNAF M-3710.7, which of the following is NOT listed as preflight planning information the PIC should be familiar with?", o:["Available weather reports and forecasts", "NOTAMs", "Aircraft maintenance discrepancy history for the past 30 days", "Fuel requirements"], a:2, r:"Maintenance discrepancy history. The five listed items are: weather reports and forecasts, NOTAMs, fuel requirements, alternate airfields available, and any anticipated traffic delays.", ref:"Ch 5-1, EO 2.138"},
    {q:"What is the primary purpose of a flight plan?", o:["To provide directional guidance from ATC", "To establish a baseline for lost communication and lost/missing aircraft procedures", "To reserve a parking spot at the destination airfield", "To document fuel purchases"], a:1, r:"Baseline for lost communication and lost/missing aircraft procedures. \"Its primary purpose is establishing a baseline for lost communication and lost/missing aircraft procedures if necessary.\"", ref:"Ch 5-1, EO 2.139"},
    {q:"Both the FAR and CNAF M-3710.7 allow a pilot to deviate from established rules under what circumstance?", o:["At the pilot's discretion", "When directed by the squadron Executive Officer", "During emergencies requiring immediate action", "Whenever the weather is unforecast"], a:2, r:"Emergencies requiring immediate action. \"Both the FAR and CNAF M-3710.7 allow pilots to deviate from established rules during emergencies requiring immediate action.\" The PIC must be ready to answer to proper authorities.", ref:"Ch 5-1, EO 2.141"},
    {q:"Runways are numbered in relation to the:", o:["True azimuth of their centerline rounded to the nearest ten degrees", "Magnetic azimuth of their centerline rounded to the nearest ten degrees", "True azimuth of the upwind leg rounded to the nearest five degrees", "Magnetic heading of the downwind leg"], a:1, r:"Magnetic azimuth, nearest ten degrees. \"Runways are numbered in relation to the magnetic azimuth of their centerline rounded off to the nearest ten degrees.\" Note: magnetic, not true.", ref:"Ch 5-2, EO 2.146"},
    {q:"A runway running east and west, approached from the west on a heading of 090\u00b0, would be designated:", o:["Runway 09", "Runway 27", "Runway 18", "Runway 36"], a:0, r:"Runway 09. Runway numbers are determined from the direction the aircraft approaches. Approached from the west on 090\u00b0 = Runway 09; the same pavement from the east = Runway 27.", ref:"Ch 5-2, EO 2.146"},
    {q:"You are inbound to land and observe a steady green Aldis lamp signal. This means:", o:["Return for landing", "Cleared to land", "Give way to other aircraft and continue circling", "Airport unsafe, do not land"], a:1, r:"Cleared to land. Table 2-1: steady green, aircraft in flight = cleared to land. (Steady green on the ground = cleared to takeoff.)", ref:"Ch 5-2, EO 2.147"},
    {q:"You are on the ground and observe a flashing white Aldis lamp signal. This means:", o:["Cleared to taxi", "Taxi clear of the runway", "Return to starting point on the airport", "Exercise extreme caution"], a:2, r:"Return to starting point on the airport. Table 2-1: flashing white on the ground = return to starting point. In flight, flashing white is not used by the FAA.", ref:"Ch 5-2, EO 2.147"},
    {q:"Which airport signs have white letters on a red background?", o:["Location signs", "Direction signs", "Information signs", "Mandatory instruction signs"], a:3, r:"Mandatory instruction signs. \"Mandatory instruction signs have white letters on a red background and are used to denote the entrance to a runway or critical area or prohibited areas.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"A waveoff signal tells the pilot ______ and is ______.", o:["\"Reduce speed\"; advisory", "\"Do not land\"; mandatory except in an emergency", "\"Go around\"; optional", "\"Hold short\"; mandatory at all times"], a:1, r:"\"Do not land\"; mandatory except in an emergency. Directly from the Waveoff Signals paragraph and Assignment Sheet 5-2-3 Q4.", ref:"Ch 5-2, EO 2.147"},
    {q:"The large end of a wind cone or wind sock points:", o:["In the direction the wind is blowing", "Into the wind", "Toward the active runway", "Toward the control tower"], a:1, r:"Into the wind. \"The large end of the wind cone or wind sock points into the wind as does the large end (cross bar) of the wind tee.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"The spar of a tetrahedron points:", o:["Into the wind", "In the direction of landing", "Toward the approach end of the crosswind runway", "Toward the control tower"], a:1, r:"In the direction of landing. \"The spar of the tetrahedron points in the direction of landing.\" The tetrahedron is mechanically/manually aligned with the active runway \u2014 it does not move with the wind.", ref:"Ch 5-2, EO 2.147"},
    {q:"What color are runway edge lights?", o:["Blue", "Green", "Amber", "White"], a:3, r:"White. \"The sides of the runway are outlined by white runway edge lights.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"When viewed from an approaching aircraft, the lights marking the ends of the runway that indicate the landing threshold are:", o:["Red", "Green", "White", "Blue"], a:1, r:"Green. End-of-runway lights are green on one side, red on the other. Viewed from an approaching aircraft they are green (\"threshold lights\"); viewed from the runway they are red (\"overrun lights\").", ref:"Ch 5-2, EO 2.147"},
    {q:"Taxiways are outlined with what color lights?", o:["Blue", "Green", "White", "Red"], a:0, r:"Blue. \"Taxiways are outlined with blue lights.\" (Taxiway centerline lights are green; turnoff lights are green.)", ref:"Ch 5-2, EO 2.147"},
    {q:"For a VASI, two red lights over two white lights on final approach indicates the aircraft is:", o:["Below glideslope", "On glideslope", "Above glideslope", "Required to wave off"], a:1, r:"On glideslope. VASI near bar white, far bar red = on glideslope. Visually this reads red over white. Matches Assignment Sheet 5-2-3 Q8.", ref:"Ch 5-2, EO 2.147"},
    {q:"For a VASI, when both sets of lights appear white, the aircraft is:", o:["Too low", "On glideslope", "Too high", "Aligned with the wrong runway"], a:2, r:"Too high. \"When both sets of lights are white, the aircraft is too high. When both sets are red, the aircraft is too low.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"What are the basic VFR weather minimums for takeoff?", o:["300' / 1 SM", "1,000' / 1 SM", "1,000' / 3 SM", "3,000' / 3 SM"], a:2, r:"1,000' / 3 SM. \"For VFR takeoff, the ceiling at the point of departure must be at least 1,000' AGL, and the prevailing visibility must be 3 SM or greater.\"", ref:"Ch 5-2, EO 2.150"},
    {q:"A ceiling is defined as the lowest:", o:["Few or scattered cloud layer", "Broken or overcast cloud layer", "Scattered or broken cloud layer", "Cloud layer of any coverage"], a:1, r:"Broken or overcast. \"A ceiling is defined as the lowest broken (BKN) or overcast (OVC) cloud layer.\"", ref:"Ch 5-2, EO 2.148"},
    {q:"Aerobatic flight is defined as an intentional maneuver involving abrupt bank angles greater than ____, pitch angles greater than ____, or accelerations greater than ____.", o:["45\u00b0; \u00b130\u00b0; 1.5 g", "60\u00b0; \u00b145\u00b0; 2.0 g", "90\u00b0; \u00b160\u00b0; 3.0 g", "60\u00b0; \u00b130\u00b0; 2.5 g"], a:1, r:"60\u00b0; \u00b145\u00b0; 2.0 g. \"Aerobatic flight is defined as an intentional maneuver involving abrupt bank angles greater than 60\u00b0, pitch angles greater than \u00b145\u00b0, or accelerations greater than 2.0 g.\"", ref:"Ch 5-2, EO 2.154"},
    {q:"You are on a VFR flight above 3,000' AGL on a magnetic course of 090\u00b0. Which altitude complies with the semicircular rules?", o:["8,000' MSL", "8,500' MSL", "9,000' MSL", "9,500' MSL"], a:3, r:"9,500' MSL. Magnetic course 090\u00b0 falls in 0\u00b0\u2013179\u00b0 = east. Above 3,000' AGL and below 18,000' MSL, east = odd thousand plus 500'. 9,500 is the only odd-plus-500 option.", ref:"Ch 5-2, EO 2.153"},
    {q:"Airspace is divided into which two broad categories?", o:["Positive and negative", "Controlled and uncontrolled", "Terminal and en route", "Domestic and international"], a:1, r:"Controlled and uncontrolled. \"Airspace can be divided into two broad categories: controlled and uncontrolled.\"", ref:"Ch 5-3, EO 2.157"},
    {q:"Class A airspace generally consists of all airspace from:", o:["The surface to 10,000' MSL", "14,500' MSL to FL450", "18,000' MSL up to and including FL600", "18,000' MSL up to and including FL450"], a:2, r:"18,000' MSL up to and including FL600. Includes airspace within 12 nautical miles of the coast. FL450 is the top of the jet route structure, not Class A.", ref:"Ch 5-3, EO 2.158"},
    {q:"Unless otherwise authorized, all aircraft within Class A airspace must operate under:", o:["VFR", "VFR-on-top", "IFR", "Either VFR or IFR"], a:2, r:"IFR. \"Unless otherwise authorized, all aircraft within Class A airspace must operate under IFR. ATC will not authorize VFR or VFR-ON-TOP in Class A airspace.\"", ref:"Ch 5-3, EO 2.158"},
    {q:"Class B airspace generally extends from the surface to what altitude?", o:["4,000' AGL", "2,500' AGL", "10,000' MSL", "18,000' MSL"], a:2, r:"10,000' MSL. \"Class B airspace generally consists of that airspace from the surface to 10,000' MSL surrounding the nation's busiest airports.\"", ref:"Ch 5-3, EO 2.158"},
    {q:"Class C airspace generally consists of a ____ radius core surface area and a ____ radius shelf area.", o:["4 nm; 10 nm", "5 nm; 10 nm", "5 nm; 20 nm", "10 nm; 30 nm"], a:1, r:"5 nm core; 10 nm shelf. Core extends surface to 4,000' AGL; the 10 nm shelf extends 1,200' AGL to 4,000' AGL.", ref:"Ch 5-3, EO 2.158"},
    {q:"Class D airspace exists only when a ______ is in operation and generally extends from the surface up to but not including ______ AGL.", o:["Radar approach control; 4,000'", "Control tower; 2,500'", "Flight service station; 1,200'", "Control tower; 4,000'"], a:1, r:"Control tower; 2,500'. Class D extends from the surface to 2,500' AGL surrounding airports with an operational control tower. Matches Assignment Sheet 5-3-3 Q5.", ref:"Ch 5-3, EO 2.158"},
    {q:"The vertical dimensions of a Victor airway are 1,200' AGL up to, but NOT including:", o:["10,000' MSL", "14,500' MSL", "18,000' MSL", "FL450"], a:2, r:"18,000' MSL. Victor airways extend from 1,200' AGL to, but not including, 18,000' MSL.", ref:"Ch 5-3, EO 2.159"},
    {q:"Jet routes extend from:", o:["14,500' MSL to FL600", "18,000' MSL to FL450", "18,000' MSL to FL600", "1,200' AGL to 18,000' MSL"], a:1, r:"18,000' MSL to FL450. Jet routes are not airways; they standardize routing in Class A. The FL450 upper limit prevents interference between stations with similar NAVAID frequencies.", ref:"Ch 5-3, EO 2.159"},
    {q:"Naval aircraft position lights are:", o:["Green on the left wing, red on the right wing, white facing aft", "Red on the left wing, green on the right wing, white facing aft", "White on both wings, red facing aft", "Red on the left wing, white on the right wing, green facing aft"], a:1, r:"Red left, green right, white aft. Standard naval aircraft position light configuration per CNAF M-3710.7.", ref:"Ch 5-3, EO 2.163/2.164"},
    {q:"Position lights shall be on during the period:", o:["Sunset to sunrise", "30 minutes prior to official sunset until 30 minutes after official sunrise", "1 hour prior to official sunset until 1 hour after official sunrise", "Engine start until engine shutdown"], a:1, r:"30 minutes prior to official sunset until 30 minutes after official sunrise. Also required any time flight visibility from the cockpit is less than 3 SM.", ref:"Ch 5-3, EO 2.163"},
    {q:"Anti-collision lights shall be used from:", o:["30 minutes before sunset to 30 minutes after sunrise", "Takeoff until landing", "Before engine start until engine shutdown", "Only during hours of darkness"], a:2, r:"Before engine start until engine shutdown. They may be turned off in clouds and when they adversely affect ground operations.", ref:"Ch 5-3, EO 2.163"},
    {q:"When two aircraft are approaching each other head-on, or nearly so, at the same altitude:", o:["The aircraft on the right has the right of way", "Each pilot shall alter course to the right", "Each pilot shall alter course to the left", "The faster aircraft shall descend"], a:1, r:"Each pilot shall alter course to the right. \"When aircraft are approaching each other head-on, or nearly so, at the same altitude, each pilot of each aircraft shall alter course to the right to pass well clear.\" This applies regardless of category.", ref:"Ch 5-3, EO 2.165"},
    {q:"Which aircraft has the right of way over all other air traffic?", o:["An aircraft in distress", "An aircraft on final approach", "A balloon", "An aircraft being overtaken"], a:0, r:"An aircraft in distress. \"An aircraft in distress has the right of way over all other air traffic.\"", ref:"Ch 5-3, EO 2.165"},
    {q:"FAR Part 91 imposes a maximum airspeed of ______ below 10,000' MSL.", o:["200 KIAS", "250 KIAS", "265 KIAS", "300 KIAS"], a:1, r:"250 KIAS. FAR Part 91 airspeed limit below 10,000' MSL. (200 KIAS is the limit below the lateral limits of Class B and within 4 nm of a Class C/D primary airport.)", ref:"Ch 5-3, EO 2.167"},
    {q:"When flying over a congested area of a city, town, or settlement, a pilot shall maintain an altitude of:", o:["500' above the highest obstacle within 1,000' of the aircraft", "1,000' above the highest obstacle within 2,000' horizontal radius of the aircraft", "2,000' above the highest obstacle within 1,000' of the aircraft", "3,000' AGL"], a:1, r:"1,000' above the highest obstacle within a 2,000' horizontal radius. Directly from the FAR Part 91 minimum safe altitude over congested areas.", ref:"Ch 5-3, EO 2.166"},
    {q:"Any maneuver conducted at low altitude and/or a high rate of speed for thrill purposes over land or water is considered:", o:["Zooming", "An unusual attitude", "Flat hatting", "Autorotation"], a:2, r:"Flat hatting. CNAF M-3710.7 prohibits flat hatting \u2014 maneuvers at low altitude and/or high speed for thrill purposes over land or water.", ref:"Ch 5-3, EO 2.171"},
  ]
},
{
  name: "Test 2 \u2014 Medium",
  desc: "Two-part stems, applied relationships, and plausible near-miss distractors.",
  questions: [
    {q:"Which statement correctly describes the relationship between FAR Part 91 and CNAF M-3710.7?", o:["Naval aircraft are exempt from FAR Part 91 when operating outside the continental United States", "Naval aircraft shall be operated in accordance with FAR Part 91 except where CNAF M-3710.7 prescribes more stringent requirements", "CNAF M-3710.7 replaces FAR Part 91 for all military aircraft worldwide", "FAR Part 91 supersedes CNAF M-3710.7 whenever the two conflict"], a:1, r:"CNAF M-3710.7 states that \"Naval aircraft shall be operated in accordance with applicable provisions of FAR Part 91 except where this manual prescribes more stringent requirements.\" The Navy is subject to both worldwide \u2014 CNAF does not replace the FAR, and the deviations granted make the Navy less restricted only in specific listed areas.", ref:"Ch 5-1, EO 2.133"},
    {q:"In which of the following areas has the FAA permitted the Department of the Navy to depart from FAR Part 91?", o:["Right-of-way rules and aircraft lighting", "Aircraft speed, minimum fuel, and alternate airport weather", "Airspace classification and Mode C requirements", "Aerobatic flight altitudes and airport signage"], a:1, r:"The guide lists departures from the FAR in the areas of aircraft speed, minimum fuel, alternate airport weather, special mission, and low-level mission requirements.", ref:"Ch 5-1, EO 2.133"},
    {q:"Which of the following lists the priority of regulations in the correct order, highest to lowest?", o:["CNAF M-3710.7, NATOPS Flight Manual, FAR Part 91, FLIPs", "FAR Part 91, FLIPs, CNAF M-3710.7, NATOPS Flight Manual", "NATOPS Flight Manual, CNAF M-3710.7, FLIPs, FAR Part 91", "NATOPS Flight Manual, FLIPs, CNAF M-3710.7, FAR Part 91"], a:2, r:"Priority of Regulations: (1) NATOPS Flight Manual, (2) CNAF M-3710.7, (3) FLIPs, (4) FAR Part 91. Note that FLIPs (DoD) sit above the FAR but below the Navy's own publications.", ref:"Ch 5-1, EO 2.134"},
    {q:"In NATOPS terminology, the word \"will\":", o:["Indicates a mandatory procedure", "Indicates a recommended procedure", "Indicates futurity and never indicates any degree of requirement", "Is used interchangeably with \"shall\""], a:2, r:"\"'Will' indicates futurity and never indicates any degree of requirement for application of a procedure.\" This is the one NATOPS word with no compliance weight at all.", ref:"Ch 5-1, EO 2.135"},
    {q:"Which statement correctly describes ADS-B?", o:["ADS-B Out delivers weather and traffic directly to the cockpit", "ADS-B In broadcasts the aircraft's GPS position and altitude to ground stations once per second", "ADS-B Out broadcasts GPS location, altitude, and ground speed to ground stations and other aircraft once per second", "ADS-B replaces the requirement for a Mode 3 transponder"], a:2, r:"ADS-B Out broadcasts GPS location, altitude, ground speed, and other data to ground stations and other aircraft once per second. ADS-B In delivers weather and traffic to the cockpit. Answer (a) and (b) reverse the two.", ref:"Ch 5-1, EO 2.132/2.160"},
    {q:"A notice containing information concerning the establishment, condition, or change in any aeronautical facility, service, procedure, or hazard which is temporary in nature is a:", o:["FLIP", "NOTAM", "Flight advisory", "ATIS broadcast"], a:1, r:"NOTAM. Verbatim definition of Notice to Air Mission from the Aviation Terminology section.", ref:"Ch 5-1, EO 2.132"},
    {q:"Which statement about Clearance Delivery is correct?", o:["It has radar surveillance capability but no control authority", "It relays ATC clearances to departing aircraft and has no control or surveillance capabilities", "It is always a separate station with its own controller at every airport", "It is a sub-agency of the ARTCC rather than the Control Tower"], a:1, r:"\"Clearance Delivery relays ATC clearances to departing aircraft and has no control or surveillance capabilities.\" At some airports the function is handled by Ground, so (c) is false.", ref:"Ch 5-1, EO 2.136"},
    {q:"A TRACON will normally operate how many frequencies in each sector, and for what purpose?", o:["One frequency for all terminal traffic", "Two \u2014 \"Approach\" for arriving traffic and \"Departure\" for departing traffic", "Three \u2014 Clearance Delivery, Ground, and Tower", "Two \u2014 one for IFR traffic and one for VFR traffic"], a:1, r:"\"TRACON will normally operate two frequencies in each sector, 'Approach' for arriving traffic and 'Departure' for departing traffic.\" Option (c) describes the Control Tower's three stations.", ref:"Ch 5-1, EO 2.136"},
    {q:"Which of the following is the CNAF M-3710.7 definition of Pilot in Command?", o:["The pilot responsible for the operation and safety of an aircraft during flight time and the final authority as to the operation of that aircraft", "The pilot assigned by the unit commander, or a delegated authority, the responsibility for the safe, orderly flight of the aircraft and well-being of the crew", "The person aboard the aircraft ultimately responsible for its operation and safety during flight", "The person legally in charge of the aircraft, normally liable for infractions of any flight rule"], a:1, r:"CNAF M-3710.7 defines PIC as the pilot assigned by the unit commander, or a delegated authority, the responsibility for the safe, orderly flight of the aircraft and well-being of the crew. Option (a) is the FAA definition.", ref:"Ch 5-1, EO 2.137"},
    {q:"Which of the following is NOT among the preflight planning items listed in CNAF M-3710.7?", o:["Alternate airfields available if the flight cannot be completed as planned", "Any anticipated traffic delays", "Prior permission required (PPR) confirmation for the departure airfield", "Available weather reports and forecasts"], a:2, r:"PPR confirmation. PPR is a real requirement, but it appears under Authorized Airfields, not in the five listed preflight planning items (weather, NOTAMs, fuel, alternates, anticipated traffic delays). This distinction is exactly the kind of thing the exam separates.", ref:"Ch 5-1, EO 2.138/2.142"},
    {q:"A DD-175-1 flight weather brief is valid for:", o:["3.0 hours past brief time or ETD plus 30 minutes, whichever is earlier", "4.0 hours past brief time or ETD plus 45 minutes, whichever is later", "24 hours past brief time or ETD plus 1 hour, whichever is earlier", "2.0 hours past brief time or ETD plus 20 minutes, whichever is earlier"], a:0, r:"\"DD-175-1 briefs are only valid for 3.0 hours past briefing/FWB delivery time or estimated time of departure (ETD) plus 30 minutes, whichever time is earlier.\"", ref:"Ch 5-1, EO 2.140"},
    {q:"Which flight plan form is used for other than local flights originating from airfields in the United States at which a military operations department is located?", o:["FAA Form 7233-1", "DD Form 1801", "The squadron flight schedule", "DD Form 175-1"], a:1, r:"DD Form 1801. Used for other than local flights originating from U.S. airfields with a military operations department. FAA Form 7233-1 is used at U.S. airfields without one; DD-175-1 is the weather brief, not a flight plan.", ref:"Ch 5-1, EO 2.139"},
    {q:"At a nonmilitary installation, the pilot shall close the flight plan with:", o:["Base Operations", "The Control Tower", "Flight Service Station", "ARTCC"], a:2, r:"FSS. At military installations the pilot confirms closure with tower or base operations; at nonmilitary installations the pilot closes with FSS through any means of communication available.", ref:"Ch 5-1, EO 2.142"},
    {q:"Per CNAF M-3710.7, safety belts and shoulder harnesses shall be worn:", o:["From engine start until engine shutdown, with no exceptions", "Tightened prior to takeoff and worn until completion of the flight, except when necessary activities require temporary removal", "Only during takeoff, landing, and aerobatic flight", "Whenever the aircraft is operating in IMC"], a:1, r:"\"Each person's safety belt and shoulder harness shall be worn and tightened prior to takeoff and shall be worn until completion of the flight except when necessary activities require temporary removal.\"", ref:"Ch 5-1, EO 2.143"},
    {q:"Of all causes of fatigue, which is described as one of the most treatable?", o:["Lack of sleep", "Dehydration", "Poor nutrition", "Circadian desynchrony"], a:1, r:"Dehydration. \"Of all causes of fatigue, one of the most treatable is dehydration.\" Lack of sleep is a principal factor but is not the one the guide singles out as most treatable.", ref:"Ch 5-1, EO 2.144"},
    {q:"Crew rest must include an opportunity for how many hours of uninterrupted sleep in every 24-hour period?", o:["6", "8", "10", "12"], a:1, r:"8 hours. Crew rest \"must include an opportunity for 8 hours of uninterrupted sleep time for every 24-hour period.\" Do not confuse this with the 16/18-hour continuous-wakefulness performance figures.", ref:"Ch 5-1, EO 2.145"},
    {q:"What is the recommended maximum daily caffeine intake for flight personnel?", o:["250 mg per day", "450 mg per day (3 to 4 cups of drip coffee)", "600 mg per day (5 to 6 cups of drip coffee)", "There is no recommended maximum"], a:1, r:"450 mg per day (3\u20134 cups of drip coffee). Both the milligram figure and the cup equivalent are correct; Assignment Sheet 5-1-3 Q19 answers \"Both A & B.\"", ref:"Ch 5-1, EO 2.145"},
    {q:"Use of both prescription and over-the-counter drugs is prohibited for flight personnel unless specifically approved by:", o:["The unit commanding officer", "A Naval Aerospace Physiologist", "A Flight Surgeon", "BUMED"], a:2, r:"A Flight Surgeon. Drugs (prescription and OTC) require FS approval. BUMED is the authority for nutritional/dietary supplements \u2014 a very common swap on the exam.", ref:"Ch 5-1, EO 2.145"},
    {q:"You are inbound to land and observe a flashing red Aldis lamp signal. This means:", o:["Taxi clear of the runway", "Airport unsafe, do not land", "Give way to other aircraft and continue circling", "Return for landing"], a:1, r:"Airport unsafe, do not land. Table 2-1: flashing red in flight = airport unsafe, do not land. On the ground it means taxi clear of the runway.", ref:"Ch 5-2, EO 2.147"},
    {q:"You are inbound to land and observe a steady red Aldis lamp signal. This means:", o:["Stop", "Give way to other aircraft and continue circling", "Airport unsafe, do not land", "Exercise extreme caution"], a:1, r:"Give way to other aircraft and continue circling. Table 2-1: steady red in flight. On the ground, steady red means stop.", ref:"Ch 5-2, EO 2.147"},
    {q:"An alternating red and green Aldis lamp signal means:", o:["Cleared to land", "Return to starting point", "Exercise extreme caution", "Has no meaning in flight"], a:2, r:"Exercise extreme caution. Alternating red and green means the same thing both on the ground and in the air.", ref:"Ch 5-2, EO 2.147"},
    {q:"A flashing white Aldis lamp signal directed at an aircraft in flight:", o:["Means return for landing", "Means cleared to land", "Is not used by the FAA", "Means airport unsafe"], a:2, r:"Not used by the FAA. Flashing white has meaning only on the ground (return to starting point). Assignment Sheet 5-2-3 Q2 pairs it with \"has no meaning.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"A runway holding position marking (hold short line) consists of:", o:["Two yellow lines, one solid and one dashed, with the solid line on the nonmovement side", "Four yellow lines (two solid and two dashed), with the solid lines always on the side where the aircraft must hold", "Two yellow solid lines spaced two feet apart connected by pairs of solid lines", "Four white lines extending across the width of the runway"], a:1, r:"Four yellow lines, two solid and two dashed, extending across the taxiway; the solid lines are always on the side where the aircraft must hold. Option (a) describes nonmovement area boundary markings; (c) describes ILS holding position markings.", ref:"Ch 5-2, EO 2.147"},
    {q:"Runway distance remaining signs have:", o:["Black numbers on a yellow background", "White numbers on a black background", "White numbers on a red background", "Yellow numbers with a yellow border on a black background"], a:1, r:"White numbers on a black background. They indicate landing distance remaining in thousands of feet.", ref:"Ch 5-2, EO 2.147"},
    {q:"Direction signs, used at the intersection of taxiways to indicate the direction of turn, have:", o:["White letters on a red background", "Black letters on a yellow background", "Yellow letters and a yellow border on a black background", "White numbers on a black background"], a:1, r:"Black letters on a yellow background. Same scheme as destination and information signs. Option (c) is the taxiway location sign.", ref:"Ch 5-2, EO 2.147"},
    {q:"The lighting of a tetrahedron is similar to an aircraft's, with:", o:["Green lights on the left side and red lights on the right side and spar", "Red lights on the left side and green lights on the right side, central ridge, and spar", "White lights on the spar and red lights on both sides", "Amber lights on the central ridge only"], a:1, r:"\"Its lighting is similar to an aircraft's with red lights on the left side and green lights on the right side, central ridge, and spar.\" Note the spar carries green \u2014 a frequent distractor reverses this.", ref:"Ch 5-2, EO 2.147"},
    {q:"Which statement about the tetrahedron is TRUE?", o:["It is a free-swinging indicator that turns with the wind", "It is mechanically or manually aligned with the active runway and does not move with the wind", "It indicates approximate wind velocity as well as direction", "It may only be used during daylight hours"], a:1, r:"\"A tetrahedron is mechanically or manually aligned with the active runway; it does not move with the wind.\" That is why pilots are cautioned about using it in light or calm wind. The windsock is the free-swinging indicator that shows velocity. Lighting is permitted during darkness, so (d) is false.", ref:"Ch 5-2, EO 2.147"},
    {q:"Touchdown Zone Lighting (TDZL) consists of two rows of ____ light bars on both sides of the runway centerline, extending approximately ____ down the runway or to the midpoint, whichever is less.", o:["Green; 2,000'", "White; 3,000'", "Amber; 3,000'", "White; 1,500'"], a:1, r:"White; 3,000'. TDZL is two rows of white light bars extending approximately 3,000' down the runway or to the midpoint, whichever is less.", ref:"Ch 5-2, EO 2.147"},
    {q:"Viewed from the landing threshold, Runway Centerline Lighting (RCLS) is white until the last 3,000' of runway. What is the sequence after that?", o:["Alternating white and red for 2,000', then red for the last 1,000'", "Red for 2,000', then alternating white and red for the last 1,000'", "Alternating white and green for 2,000', then green for the last 1,000'", "Amber for 2,000', then red for the last 1,000'"], a:0, r:"RCLS: white until the last 3,000'; white alternating with red for the next 2,000'; red for the final 1,000'.", ref:"Ch 5-2, EO 2.147"},
    {q:"A military airport rotating beacon can be distinguished from a civilian beacon by:", o:["A solid white light alternating with a solid green light", "Dual-peaked (two quick) white flashes alternating with a solid green flash", "A red light alternating with a green light", "Three white flashes alternating with a red flash"], a:1, r:"A military beacon shows dual-peaked (two quick) white flashes alternating with a solid green flash. A civilian beacon is a solid white alternating with solid green.", ref:"Ch 5-2, EO 2.147"},
    {q:"Which statement about the PAPI is correct?", o:["It consists of a near bar and a far bar of lights", "It is installed in a single row of either two or four light units, normally on the left side of the runway", "It is installed only on precision instrument runways with an ALS", "It is visible from about 20 miles during the day and 5 miles at night"], a:1, r:"PAPI uses light units similar to VASI but installed in a single row of either two or four units, normally on the left side of the runway. It is visible about 5 miles by day and up to 20 miles at night \u2014 option (d) reverses these. The near bar/far bar arrangement is the VASI.", ref:"Ch 5-2, EO 2.147"},
    {q:"According to CNAF M-3710.7, Instrument Meteorological Conditions also exist any time:", o:["The aircraft is operating above 18,000' MSL", "A visible horizon is not distinguishable", "Visibility is less than 5 statute miles", "The aircraft is on an IFR flight plan"], a:1, r:"\"According to CNAF M-3710.7, Instrument Meteorological Conditions also exist any time a visible horizon is not distinguishable.\"", ref:"Ch 5-2, EO 2.148"},
    {q:"Which of the following is NOT one of the PIC's listed alternatives when en route weather precludes compliance with VFR minimums?", o:["Alter route of flight so as to continue under VMC", "Remain in VMC until a change of flight plan is filed and IFR clearance is obtained", "Remain in VMC and land at a suitable alternate", "Continue to destination under VFR while remaining clear of clouds"], a:3, r:"The three listed alternatives are: alter route to continue under VMC; remain VMC until a change of flight plan is filed and IFR clearance is obtained; or remain VMC and land at a suitable alternate. Pressing on into conditions below VFR minimums is not one of them.", ref:"Ch 5-2, EO 2.151"},
    {q:"CNAF M-3710.7 requires all aircraft to carry sufficient usable fuel to fly from takeoff to the destination plus a reserve of:", o:["5% of planned fuel requirements, never less than 10 minutes of flight", "10% of planned fuel requirements, never less than 20 minutes of flight", "10% of planned fuel requirements, never less than 45 minutes of flight", "20% of planned fuel requirements, never less than 30 minutes of flight"], a:1, r:"10% of planned fuel requirements, and in no case less than 20 minutes of flight time. For the T-6 and all turbine-powered fixed-wing aircraft, reserve is computed at max endurance at 10,000' MSL.", ref:"Ch 5-2, EO 2.150"},
    {q:"For the purposes of entry into Class C airspace, two-way radio communication is considered established when:", o:["The pilot transmits his request on the correct frequency", "ATC responds with the aircraft's specific call sign", "ATC issues a discrete transponder code", "ATC responds in any manner to any aircraft on the frequency"], a:1, r:"Two-way communications are established when ATC responds with the aircraft's specific call sign. \"Aircraft calling Pensacola Approach, stand by\" does not establish comms.", ref:"Ch 5-3, EO 2.158"},
    {q:"To operate a fixed-wing aircraft in Class B airspace, the pilot must at a minimum be a:", o:["Student pilot with an endorsement", "Private pilot certificate holder, or a designated aviator when flying a military aircraft", "Commercial pilot certificate holder", "Instrument-rated airline transport pilot"], a:1, r:"\"The pilot must have at least a Private Pilot Certificate (designated aviator when flying a military aircraft).\"", ref:"Ch 5-3, EO 2.158"},
    {q:"Unless designated at a lower altitude, Class E airspace begins at:", o:["700' AGL", "1,200' AGL", "14,500' MSL", "18,000' MSL"], a:2, r:"14,500' MSL. Unless designated at a lower altitude, Class E begins at 14,500' MSL (excluding airspace less than 1,500' AGL). The 700' and 1,200' AGL figures are the designated lower floors.", ref:"Ch 5-3, EO 2.158"},
    {q:"Which statement about entry requirements for Class E airspace is correct?", o:["A Mode C transponder and two-way radio communications are required", "An ATC clearance is required for all through-flights", "There are no specific pilot certification, equipment, arrival, or through-flight entry requirements", "Only instrument-rated pilots may operate in Class E airspace"], a:2, r:"\"There are no specific pilot certification, equipment, arrival, or through-flight entry requirements for Class E airspace.\" The guide's memorable phrasing: it is controlled airspace, but you must volunteer for control.", ref:"Ch 5-3, EO 2.158"},
    {q:"What is the width of a Victor airway?", o:["4 nm total, 2 nm either side of centerline", "8 nm total, 4 nm either side of centerline", "10 nm total, 5 nm either side of centerline", "Victor airways have no defined width"], a:1, r:"8 nm total, 4 nm either side of centerline. Jet routes, by contrast, have no defined width.", ref:"Ch 5-3, EO 2.159"},
    {q:"In addition to the requirements of Class A, B, and C airspace, an operable Mode C transponder is required in:", o:["All airspace at and above 10,000' MSL", "All airspace at and above 14,500' MSL", "All Class E airspace", "All airspace within 10 nm of a Class D airport"], a:0, r:"All airspace at and above 10,000' MSL. Also required within 30 nm of a Class B airport surface to 10,000' MSL, in extensions beyond 30 nm above the ceiling up to 10,000' MSL, and above a Class C ceiling and lateral boundaries up to 10,000' MSL.", ref:"Ch 5-3, EO 2.160"},
    {q:"What are the VFR weather minimums for Class B airspace?", o:["3 miles visibility; 500' below, 1,000' above, 2,000' horizontal", "3 miles visibility; clear of clouds", "1 mile visibility; clear of clouds", "5 miles visibility; 1,000' below, 1,000' above, 1 SM horizontal"], a:1, r:"3 miles visibility, clear of clouds. Class B is the only classification with a \"clear of clouds\" requirement at 3 SM; Class G day below 1,200' AGL is clear of clouds at 1 SM.", ref:"Ch 5-3, EO 2.161"},
    {q:"When flying VFR in Class E airspace above 10,000' MSL, you must maintain:", o:["1,000' above, 500' below, 2,000' horizontal, 3 SM visibility", "1,000' above, 1,000' below, 1 SM horizontal, 5 SM visibility", "500' above, 1,000' below, 2,000' horizontal, 3 SM visibility", "Clear of clouds, 1 SM visibility"], a:1, r:"Class E above 10,000' MSL requires 5 SM visibility with 1,000' below, 1,000' above, and 1 SM horizontal cloud clearance.", ref:"Ch 5-3, EO 2.161"},
    {q:"Which statement about Warning Areas is correct?", o:["They are established within the three-mile limit only", "They may contain hazards to nonparticipating aircraft and are generally in international airspace; permission is not required prior to entry", "Aircraft must obtain prior approval from the controlling agency before entry", "The FAA has full jurisdiction over activities conducted within them"], a:1, r:"Warning Areas are established beyond the three-mile limit over domestic waters, international waters, or both; the FAA has no jurisdiction over international airspace, and aircraft need not receive permission prior to entry \u2014 though entering without coordination is at your own risk.", ref:"Ch 5-3, EO 2.162"},
    {q:"A Military Operations Area (MOA) is established for the purpose of:", o:["Prohibiting all civil traffic for reasons of national security", "Separating certain military training activities from IFR traffic", "Warning pilots of a high volume of pilot training or unusual aerial activity", "Containing artillery firing and guided missile hazards"], a:1, r:"MOAs are established \"for the purpose of separating certain military training activities from IFR traffic.\" Option (c) describes an Alert Area; (d) describes a Restricted Area; (a) describes a Prohibited Area.", ref:"Ch 5-3, EO 2.162"},
    {q:"In order to fly through a Restricted Area, an aircraft must:", o:["Have prior approval granted by the using or controlling authority", "Simply monitor the appropriate FSS frequency", "Remain VFR and exercise extreme caution", "File an IFR flight plan; no approval is required"], a:0, r:"\"In order to fly through these areas, aircraft must have prior approval granted by the controlling authority.\" Restricted Areas are the special use airspace that requires permission.", ref:"Ch 5-3, EO 2.162"},
    {q:"When two aircraft of the same category are converging at approximately the same altitude (other than head-on):", o:["The aircraft on the left has the right of way", "The aircraft to the other's right has the right of way", "The faster aircraft has the right of way", "The lower aircraft has the right of way"], a:1, r:"\"When aircraft of the same category are converging at approximately the same altitude (except head-on, or nearly so) the aircraft to the other's right has the right of way.\"", ref:"Ch 5-3, EO 2.165"},
    {q:"Which of the following aircraft categories has the HIGHEST right-of-way priority?", o:["Airplane", "Helicopter", "Airship", "Balloon"], a:3, r:"Balloon. Right-of-way category priority is based on maneuverability, least maneuverable highest: Balloon > Glider > Airship > Airplane/Helicopter.", ref:"Ch 5-3, EO 2.165"},
    {q:"An aircraft is being overtaken. Which statement is correct?", o:["The overtaking aircraft has the right of way and may pass on either side", "The aircraft being overtaken has the right of way; the overtaking aircraft shall alter course to the right and pass well clear", "The aircraft being overtaken shall alter course to the right", "Both aircraft shall alter course to the right"], a:1, r:"\"An aircraft that is being overtaken has the right of way, and the pilot of an overtaking aircraft shall alter course to the right to pass well clear.\"", ref:"Ch 5-3, EO 2.165"},
    {q:"What is the maximum airspeed permitted beneath the lateral limits of Class B airspace?", o:["250 KIAS", "230 KIAS", "200 KIAS", "175 KIAS"], a:2, r:"200 KIAS. Inside Class B the limit is 250 knots; below and no further than the lateral limits (the \"shelf\" or underlying area) it is 200 knots. Matches Assignment Sheet 5-3-3 Q20.", ref:"Ch 5-3, EO 2.167"},
    {q:"CNAF M-3710.7 states that pilots shall avoid noise-sensitive and wilderness areas when at altitudes of less than:", o:["1,000' AGL", "2,000' AGL", "3,000' AGL", "5,000' AGL"], a:2, r:"3,000' AGL. Pilots shall avoid noise-sensitive and wilderness areas below 3,000' AGL, except when complying with an approved traffic or approach pattern, VFR/IFR training routes, or special use airspace. The same 3,000' AGL figure applies over known wildlife habitations.", ref:"Ch 5-3, EO 2.170"},
  ]
},
{
  name: "Test 3 \u2014 Hard",
  desc: "Deliberately close distractors and applied scenarios. Read every option before answering.",
  questions: [
    {q:"Which of the following is the FAA definition of Pilot in Command?", o:["The pilot assigned by the unit commander the responsibility for the safe, orderly flight of the aircraft and well-being of the crew", "The pilot responsible for the operation and safety of an aircraft during flight time, who is directly responsible for and is the final authority as to the operation of that aircraft", "The pilot designated by a delegated authority as responsible for the safe and orderly conduct of the flight", "The senior aviator aboard the aircraft holding the appropriate category and class ratings"], a:1, r:"The FAR defines PIC as \"the pilot responsible for the operation and safety of an aircraft during flight time\" and states the PIC is \"directly responsible for, and is the final authority as to the operation of that aircraft.\" Option (a) is the CNAF M-3710.7 definition \u2014 note its distinguishing features: assigned by the unit commander and well-being of the crew.", ref:"Ch 5-1, EO 2.137"},
    {q:"An aircraft's NATOPS Flight Manual states a minimum safe operating speed that is greater than an airspeed restriction stated in FAR Part 91. Which governs, and why?", o:["FAR Part 91, because it is federal law and binding on all aviators in U.S. airspace", "FLIPs, because DoD publications resolve conflicts between NATOPS and the FAR", "NATOPS, because CNAF M-3710.7's priority of regulations places the aircraft NATOPS Flight Manual first", "Either may be used at the PIC's discretion, provided the deviation is reported"], a:2, r:"This is the exact example given in the Priority of Regulations section: where NATOPS states a minimum safe operating speed greater than an FAR airspeed restriction, NATOPS takes precedence. Aircraft NATOPS is #1 in the priority list.", ref:"Ch 5-1, EO 2.134"},
    {q:"Which row correctly describes FLIPs \u2014 released by / where it applies / applies to?", o:["DoN / world wide / all DoN aircraft", "FAA / U.S. airspace / all aircraft in U.S. airspace", "DoD / world wide / all DoD aircraft", "DoN / world wide / specific DoN aircraft"], a:2, r:"DoD / world wide / all DoD aircraft. From Figure 1-5. Option (a) is CNAF M-3710.7; (b) is FAR Part 91; (d) is the aircraft NATOPS Flight Manual.", ref:"Ch 5-1, EO 2.134"},
    {q:"Which of the following is NOT one of the areas in which the FAA has permitted the Department of the Navy to depart from FAR Part 91?", o:["Minimum fuel", "Alternate airport weather", "Right-of-way rules", "Low-level mission requirements"], a:2, r:"Right-of-way rules. The five listed areas are aircraft speed, minimum fuel, alternate airport weather, special mission, and low-level mission requirements. Right-of-way rules are an area where CNAF is more stringent, not exempted.", ref:"Ch 5-1, EO 2.133"},
    {q:"Which statement correctly distinguishes transponder modes?", o:["Mode 3 provides pressure altitude information; Mode C is a four-digit identification code", "Mode 3 is a four-digit code identifying the aircraft to ATC; Mode C provides pressure altitude information aiding altitude deconfliction", "Mode 3 and Mode C both provide altitude information, differing only in accuracy", "Mode C broadcasts GPS position once per second to ground stations and other aircraft"], a:1, r:"Mode 3 is a four-digit code identifying the aircraft to ATC via radar; Mode C provides pressure altitude information aiding altitude deconfliction. Option (d) describes ADS-B Out.", ref:"Ch 5-1, EO 2.160"},
    {q:"Which statement concerning ATIS is TRUE?", o:["ATIS is the third station of the ATC Control Tower, after Ground and Clearance Delivery", "ATIS is a continuous broadcast of recorded non-control information and is not a station of the ATC Control Tower", "ATIS is operated by the Flight Service Station on the tower's discrete frequency", "ATIS issues taxi and takeoff clearances at high-activity terminal areas"], a:1, r:"The guide's note is explicit: ATIS is not a station of the ATC Control Tower. It is a continuous broadcast of recorded non-control information (weather, runway in use) on a discrete frequency. The Tower's three stations are Clearance Delivery, Ground, and Tower.", ref:"Ch 5-1, EO 2.136"},
    {q:"You receive your Flight Weather Brief at 0645 for a flight with an ETD of 1000. When does the brief expire?", o:["0945", "1030", "1000", "1330"], a:0, r:"0945. The brief is valid for 3.0 hours past brief time (0645 + 3:00 = 0945) or ETD + 30 minutes (1000 + 0:30 = 1030), whichever is earlier. 0945 is earlier. Notice the trap: with a late ETD, the 3-hour rule controls.", ref:"Ch 5-1, EO 2.140"},
    {q:"You are inbound to a nonmilitary field on an IFR flight plan and cancel IFR with Center 20 miles out. Which statement is correct?", o:["Cancellation of the IFR flight plan satisfies the requirement to close out the flight plan", "Cancellation does not meet the requirement for closing out the flight plan; a landing report must still be delivered", "The flight plan is automatically closed by ATC upon radar service termination", "Only the Control Tower at the destination may close the flight plan"], a:1, r:"\"Cancellation of an instrument flight plan (and proceeding VFR) does not meet the requirement for 'closing out' the flight plan. When a landing report has been properly delivered, the flight plan will be considered closed out.\" At a nonmilitary field, close with FSS.", ref:"Ch 5-1, EO 2.142"},
    {q:"Navy and Marine Corps flight personnel are NOT authorized to purchase aircraft fuel from other than military or government contract sources except when:", o:["The commanding officer approves the purchase in advance", "Contract fuel is available but priced higher than the local commercial rate", "Mission requirements dictated stopping at a facility without military or contract fuel sources", "The flight is a cross-country training flight approved by the operations officer"], a:2, r:"The three exceptions are: mission requirements dictated stopping at a facility without military or contract fuel sources; the flight terminated as the result of an emergency; and the flight terminated at an alternate airport in lieu of filed destination. Convenience, price, and CO approval are not among them.", ref:"Ch 5-1, EO 2.142"},
    {q:"Certain items of aircrew personal protective equipment are marked with an asterisk. These items may be omitted:", o:["By any flight personnel at the discretion of the PIC", "By flight personnel in fixed-wing cargo/transport class aircraft if the flight does not involve carrier operations and omission is approved by the commanding officer", "By all flight personnel during local training flights under 1.5 hours", "Only when specifically waived by a Flight Surgeon"], a:1, r:"Asterisked items may be omitted by flight personnel flying fixed-wing cargo/transport class aircraft (C-130, C-2, etc.) if the flight does not involve carrier operations and omission is approved by the commanding officer.", ref:"Ch 5-1, EO 2.143"},
    {q:"Inflatable life preservers shall be worn when mission requirements dictate operation over water below:", o:["500 feet", "1,000 feet", "1,500 feet", "3,000 feet"], a:1, r:"1,000 feet. \"Life preservers shall be worn when mission requirements dictate operation over water below 1,000 feet exclusive of normal departures or approaches.\"", ref:"Ch 5-1, EO 2.143"},
    {q:"Supplemental Emergency Breathing Devices (SEBD) shall be carried during overwater flight by aircrew of which aircraft?", o:["All naval aircraft", "All ejection seat aircraft", "Helicopter, tilt rotor, E-2, and C-2", "Fixed-wing cargo/transport aircraft only"], a:2, r:"Helicopter, tilt rotor, E-2, and C-2 aircrew. SEBD is carried by these communities during overwater flight.", ref:"Ch 5-1, EO 2.143"},
    {q:"Flight personnel shall not participate in flight duties or perform low-pressure chamber runs for how long following donation of 450 cc of blood?", o:["12 hours", "24 hours", "4 days", "7 days"], a:2, r:"4 days. No flight duties or low-pressure chamber runs for 4 days following donation of 450 cc (1 pint). Do not confuse with the 12-hour immunization rule.", ref:"Ch 5-1, EO 2.145"},
    {q:"Flight personnel shall not participate in flight duties for how long after receiving an immunization or injection, unless cleared sooner by a Flight Surgeon?", o:["4 hours", "12 hours", "24 hours", "48 hours"], a:1, r:"12 hours. Note this shares the same number as the alcohol restriction and the nutrition figure \u2014 three separate 12-hour rules in the aeromedical section.", ref:"Ch 5-1, EO 2.145"},
    {q:"After crossing eight time zones, how many days of accommodation should be allowed?", o:["3 days", "5 days", "8 days", "11 days"], a:1, r:"5 days. \"The accommodation period can be estimated by allowing one day for every time zone crossed in excess of three time zones.\" Eight zones \u2212 three = five days. Answering \"8\" means missing the \"in excess of three\" qualifier.", ref:"Ch 5-1, EO 2.145"},
    {q:"According to CNAF M-3710.7, as time continuously awake exceeds ____ hours performance efficiency begins to drop, and after ____ hours it rapidly declines to 75 percent of effectiveness or less.", o:["12; 16", "14; 18", "16; 18", "18; 24"], a:2, r:"16; 18. Performance efficiency begins to drop after 16 hours continuously awake and declines rapidly to 75 percent or less after 18 hours. Accident rates increase after 18 hours of wakefulness.", ref:"Ch 5-1, EO 2.145"},
    {q:"Failure to eat within how many hours preceding the end of flight may impair performance and the ability to adequately control the aircraft?", o:["6 hours", "8 hours", "12 hours", "18 hours"], a:2, r:"12 hours. \"Failure to eat within 12 hours preceding end of flight may impair performance and ability to adequately control aircraft.\"", ref:"Ch 5-1, EO 2.145"},
    {q:"Which statement about alcohol is correct per CNAF M-3710.7?", o:["Adherence to the 12-hour rule guarantees a crewmember will be free from the effects of alcohol", "Alcohol can adversely affect the vestibular system for as long as 48 hours even when blood alcohol content is zero", "A symptomatic hangover is permissible provided blood alcohol content is zero", "The 12-hour restriction is measured from takeoff, not from the mission brief"], a:1, r:"The guide states alcohol can adversely affect the vestibular system for as long as 48 hours even when blood alcohol content is zero, and explicitly warns that \"adherence to the letter of this rule does not guarantee a crewmember will be free from the effects of alcohol\" \u2014 which makes (a) false. Detectable blood alcohol or symptomatic hangover is cause for grounding, so (c) is false. The 12 hours runs from the mission brief or flight planning, so (d) is false.", ref:"Ch 5-1, EO 2.145"},
    {q:"While on a heading of 270\u00b0, you observe the tetrahedron with its spar pointing 90\u00b0 right relative to the aircraft's heading. On which runway should you land?", o:["Runway 09", "Runway 18", "Runway 27", "Runway 36"], a:3, r:"Runway 36. The spar points in the direction of landing. Heading 270\u00b0 + 90\u00b0 right = 360\u00b0. Land on Runway 36.", ref:"Ch 5-2, EO 2.147"},
    {q:"A pilot approaches an airport from the west. The pilot sights the tetrahedron with its spar pointing 90\u00b0 left relative to the aircraft's heading. The wind is from:", o:["090", "180", "270", "360"], a:3, r:"360. Approaching from the west means flying east, heading 090\u00b0. Spar 90\u00b0 left = 090\u00b0 \u2212 90\u00b0 = 360\u00b0, so the landing direction is 360. Aircraft land into the wind, therefore the wind is from 360.", ref:"Ch 5-2, EO 2.147"},
    {q:"You are flying a course of 235\u00b0 and observe the spar of the tetrahedron pointing directly at your aircraft. On which runway will you land?", o:["Runway 05", "Runway 14", "Runway 23", "Runway 32"], a:0, r:"Runway 05. If the spar points directly at you while you fly 235\u00b0, it points down your reciprocal: 235\u00b0 \u2212 180\u00b0 = 055\u00b0. Landing direction 055\u00b0 rounds to Runway 05.", ref:"Ch 5-2, EO 2.146/2.147"},
    {q:"You are flying a course of 135\u00b0 and observe the large end of the windsock pointing 90\u00b0 left relative to your aircraft. On which runway should you land?", o:["Runway 04", "Runway 13", "Runway 22", "Runway 31"], a:0, r:"Runway 04. The large end of the windsock points into the wind. Course 135\u00b0 \u2212 90\u00b0 = 045\u00b0, so the wind is from 045. Land into the wind: Runway 04. (Runway 22 would be landing downwind \u2014 the classic trap.)", ref:"Ch 5-2, EO 2.147"},
    {q:"Approach light systems extend into the approach area for what distances?", o:["1,400 to 1,500' for precision runways and 2,400 to 3,000' for non-precision runways", "2,400 to 3,000' for precision runways and 1,400 to 1,500' for non-precision runways", "3,000' for all instrument runways", "2,000 to 2,400' for precision runways and 1,000 to 1,200' for non-precision runways"], a:1, r:"ALS extend into the approach area 2,400 to 3,000' for precision instrument runways and 1,400 to 1,500' for non-precision runways.", ref:"Ch 5-2, EO 2.147"},
    {q:"The portion of a runway behind a displaced threshold is available for:", o:["Nothing; it may not be used", "Landings in either direction only", "Takeoffs in either direction and landings from the opposite direction", "Takeoffs from the opposite direction only"], a:2, r:"\"The portion of runway behind a displaced threshold is available for takeoffs in either direction and landings from the opposite direction.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"Regarding nonmovement area boundary markings, which statement is correct?", o:["They consist of four yellow lines, two solid and two dashed", "They consist of two yellow lines, with the solid line on the nonmovement area side and the dashed line on the movement area side", "They consist of two yellow lines, with the dashed line on the nonmovement area side", "They are painted white because they delineate an area under ATC control"], a:1, r:"Nonmovement area boundary markings are two yellow lines \u2014 one solid, one dashed \u2014 with the solid line on the nonmovement side and the dashed line on the movement (ATC-controlled) side. Option (a) describes the hold short line.", ref:"Ch 5-2, EO 2.147"},
    {q:"When instructed by ATC to hold short of the ILS critical area, pilots must stop so that:", o:["The nose of the aircraft is at the holding position marking", "No part of the aircraft extends beyond the holding position marking", "The main landing gear is clear of the two-foot spacing", "The aircraft is clear of the runway edge lights"], a:1, r:"\"Pilots MUST STOP so that no part of the aircraft extends beyond the holding position marking.\"", ref:"Ch 5-2, EO 2.147"},
    {q:"While planning an IFR flight, you compute a magnetic heading of 358\u00b0 to maintain a magnetic course of 004\u00b0. Which altitude would you request?", o:["5,000' MSL", "5,500' MSL", "6,000' MSL", "6,500' MSL"], a:0, r:"5,000' MSL. Semicircular rules use magnetic course, not heading. MC 004\u00b0 falls in 0\u00b0\u2013179\u00b0 = east. IFR eastbound uses odd thousands (no +500, which is the VFR convention). Matches Assignment Sheet 5-2-3 Q15.", ref:"Ch 5-2, EO 2.153"},
    {q:"You are on a VFR flight westbound and the cloud layer along your route is at 13,000' MSL. What is the highest altitude at which you may cruise and remain legal?", o:["12,500' MSL", "11,500' MSL", "10,500' MSL", "12,000' MSL"], a:2, r:"10,500' MSL. Westbound (180\u00b0\u2013359\u00b0) requires even thousands plus 500'. Any altitude above 10,000' MSL requires 1,000' below the clouds, so the ceiling of 13,000' MSL caps you at 12,000'. The candidate 12,500' violates cloud clearance; the next legal westbound altitude down is 10,500' MSL.", ref:"Ch 5-2, EO 2.153/2.161"},
    {q:"Which statement about VFR cruising altitudes is correct?", o:["They apply to all VFR flights regardless of altitude", "They apply only above 10,000' MSL", "They apply above 3,000' AGL; aircraft at or below 3,000' AGL may use any altitude regardless of direction of flight", "They apply above 3,000' MSL and below 14,500' MSL only"], a:2, r:"VFR cruising altitudes apply to flights above 3,000' AGL. \"Aircraft flying VFR at 3,000' AGL or below may use any altitude desired regardless of the direction of flight.\"", ref:"Ch 5-2, EO 2.153"},
    {q:"IFR semicircular cruising altitudes are used only for preflight planning and when the aircraft is flying in what airspace?", o:["Class A airspace", "Class E airspace", "Uncontrolled airspace", "Special use airspace"], a:2, r:"Uncontrolled airspace. Per Assignment Sheet 5-2-3 Q14: IFR semicircular altitudes are used only for preflight planning and when flying in uncontrolled airspace. In controlled airspace you fly the assigned altitude.", ref:"Ch 5-2, EO 2.153"},
    {q:"What is the minimum altitude for aerobatic flight in Training Command aircraft?", o:["1,500' AGL", "3,000' AGL", "5,000' AGL", "10,000' AGL"], a:2, r:"5,000' AGL. The FAR/CNAF floor is 1,500' AGL, but the guide's note states individual commands may be more restrictive, and 5,000' AGL is the minimum for aerobatic flight in Training Command aircraft.", ref:"Ch 5-2, EO 2.155"},
    {q:"Where may naval aviators legally execute aerobatic maneuvers?", o:["Over an open air assembly of persons, provided the aircraft remains above 1,500' AGL", "Within a Federal airway, provided visibility is at least 3 SM", "At or above 1,500' above the surface with at least 3 statute miles visibility, outside Class B, C, D, and E airspace designated for an airport", "Within Class A airspace in IMC with an ATC clearance"], a:2, r:"FAR Part 91 prohibits aerobatics over congested areas, over open air assemblies, within Class B/C/D/E airspace designated for an airport or within Federal airways, below 1,500' AGL, and when visibility is less than 3 SM. Option (c) is the only one that violates none of these. Matches Assignment Sheet 5-2-3 Q17.", ref:"Ch 5-2, EO 2.155"},
    {q:"Regarding unusual maneuvers within Class B, C, or D airspace, which statement is correct?", o:["A pilot may request clearance to perform them, and ATC may approve if traffic permits", "Pilots shall not perform or request clearance to perform them if not essential to the flight, and ATC personnel are not permitted to approve such a request or ask a pilot to perform them", "They are permitted only if the pilot first coordinates with the controlling FSS", "They are permitted in Class D airspace only, since no radar service is provided"], a:1, r:"CNAF M-3710.7 states pilots shall not perform or request clearance to perform unusual maneuvers in Class B, C, or D airspace if not essential to the flight, and \"ATC personnel are not permitted to approve a pilot's request or ask a pilot to perform these maneuvers.\"", ref:"Ch 5-2, EO 2.156"},
    {q:"Which of the following is NOT considered aerobatic flight?", o:["An intentional 70\u00b0 bank turn", "An intentional pitch attitude of 50\u00b0 nose low", "A \"break\" maneuver that conforms to the model NATOPS Flight Manual", "An intentional 2.5 g pull"], a:2, r:"\"A 'break' maneuver that conforms to the model NATOPS Flight Manual is not considered to be aerobatic flight.\" The other three each exceed a defining threshold (60\u00b0 bank, \u00b145\u00b0 pitch, 2.0 g) and are intentional.", ref:"Ch 5-2, EO 2.154"},
    {q:"Class A airspace overlies the continental United States and includes:", o:["Airspace within 3 nautical miles of the coast", "Airspace within 12 nautical miles of the coast", "Airspace within 30 nautical miles of the coast", "No offshore airspace; Class A ends at the shoreline"], a:1, r:"12 nautical miles. Class A extends from 18,000' MSL up to and including FL600 over the continental U.S., including airspace within 12 nm of the coast. (The 3-mile limit is the reference used for Warning Areas.)", ref:"Ch 5-3, EO 2.158"},
    {q:"The Class C shelf area typically extends:", o:["From the surface to 4,000' AGL within a 10 nm radius", "From 1,200' AGL to 4,000' AGL within a 10 nm radius", "From 700' AGL to 4,000' AGL within a 5 nm radius", "From 1,200' AGL to 2,500' AGL within a 10 nm radius"], a:1, r:"Class C usually has a 5 nm radius core from the surface to 4,000' AGL and a 10 nm radius shelf from 1,200' AGL to 4,000' AGL. Option (d) mixes in the Class D ceiling.", ref:"Ch 5-3, EO 2.158"},
    {q:"Class E airspace beginning at 14,500' MSL excludes:", o:["Airspace less than 1,200' AGL", "Airspace less than 1,500' AGL", "Airspace above 18,000' MSL only", "Airspace within 30 nm of a Class B airport"], a:1, r:"Airspace less than 1,500' AGL. The exclusion accounts for low altitudes in mountainous areas with limited radar coverage.", ref:"Ch 5-3, EO 2.158"},
    {q:"BOLO123 calls Pensacola Approach for a Class C transition and hears: \"Aircraft calling Pensacola Approach, stand by.\" Which statement is correct?", o:["Two-way communications have been established; BOLO123 may enter", "Two-way communications have not been established; BOLO123 may not legally enter the Class C airspace", "BOLO123 may enter provided it has an operable Mode C transponder", "BOLO123 may enter provided it remains clear of clouds with 3 SM visibility"], a:1, r:"Two-way communications are established only when ATC responds with the aircraft's specific call sign. A generic \"aircraft calling\" response does not establish comms, and a Mode C transponder does not substitute for the communications requirement.", ref:"Ch 5-3, EO 2.158"},
    {q:"The upper limit of the jet route structure is established at FL450 in order to:", o:["Keep jet routes below the floor of Class A airspace", "Prevent interference between stations with similar NAVAID frequencies", "Segregate turbojet traffic from turboprop traffic", "Match the ceiling of Victor airways"], a:1, r:"\"The upper limit is established to prevent interference between stations with similar NAVAID frequencies.\"", ref:"Ch 5-3, EO 2.159"},
    {q:"ADS-B Out is required in all airspace at and above 10,000' MSL over the 48 states and DC, excluding:", o:["Airspace at and below 1,200' AGL", "Airspace at and below 2,500' AGL", "Airspace within 30 nm of a Class B airport", "Class G airspace only"], a:1, r:"Airspace at and below 2,500' AGL. This exclusion appears in the ADS-B Out requirements but not in the Mode C requirements \u2014 a fine distinction the exam can exploit.", ref:"Ch 5-3, EO 2.160"},
    {q:"What are the VFR weather minimums in Class G airspace at night, below 1,200' AGL?", o:["1 mile visibility, clear of clouds", "3 miles visibility, clear of clouds", "3 miles visibility; 500' below, 1,000' above, 2,000' horizontal", "5 miles visibility; 1,000' below, 1,000' above, 1 SM horizontal"], a:2, r:"Class G at night below 1,200' AGL: 3 miles visibility with 500' below, 1,000' above, 2,000' horizontal. Only Class G day below 1,200' AGL gets 1 mile and clear of clouds.", ref:"Ch 5-3, EO 2.161"},
    {q:"What are the VFR weather minimums in Class G airspace during the day, above 1,200' AGL and below 10,000' MSL?", o:["1 mile visibility, clear of clouds", "1 mile visibility; 500' below, 1,000' above, 2,000' horizontal", "3 miles visibility; 500' below, 1,000' above, 2,000' horizontal", "5 miles visibility; 1,000' below, 1,000' above, 1 SM horizontal"], a:1, r:"Class G day, above 1,200' AGL and below 10,000' MSL: 1 mile visibility with 500' below, 1,000' above, 2,000' horizontal. Note visibility drops to 1 mile but the cloud clearances remain standard.", ref:"Ch 5-3, EO 2.161"},
    {q:"Which statement about Alert Areas is correct?", o:["Participating aircraft have the right of way over transiting aircraft", "Pilots of participating aircraft and pilots transiting the area are equally responsible for collision avoidance", "Permission from the controlling agency is required prior to entry", "All activity within an Alert Area is conducted under instrument flight rules"], a:1, r:"\"Pilots of participating aircraft as well as pilots transiting the area shall be equally responsible for collision avoidance.\" All activity is conducted in accordance with the FAR and under visual flight rules, and no permission is required to transit.", ref:"Ch 5-3, EO 2.162"},
    {q:"A C-130 departs for a night flight at 1830 and lands at 0600. Sunset occurs at 1930 and sunrise at 0500. The aircraft will have its position lights on from ____ to ____.", o:["1830 to 0600", "1830 to 0430", "1900 to 0530", "1930 to 0500"], a:2, r:"1900 to 0530. Lights on 30 minutes prior to official sunset (1930 \u2212 30 = 1900) until 30 minutes after official sunrise (0500 + 30 = 0530). The takeoff and landing times are distractors. Matches Assignment Sheet 5-3-3 Q14.", ref:"Ch 5-3, EO 2.163"},
    {q:"CNAF M-3710.7 states that anti-collision lights may be turned off:", o:["Any time the pilot determines they are not needed", "When flying through clouds and when their use adversely affects ground operations", "During all daylight operations", "When operating within Class G airspace"], a:1, r:"Anti-collision lights may be turned off when flying through clouds (to prevent distraction) and when their use adversely affects ground operations such as taxiing, arming/de-arming, and refueling.", ref:"Ch 5-3, EO 2.163"},
    {q:"Per CNAF M-3710.7, during IFR operations out of controlled airspace and unless the mission requires otherwise, an aircraft shall not be flown less than:", o:["500' above the highest terrain within 22 miles of the intended line of flight", "1,000' above the highest terrain, surface of the water, or obstacle within 22 miles of the intended line of flight; 2,000' over designated mountainous terrain", "1,000' above the highest obstacle within a 2,000' horizontal radius", "2,000' above the highest terrain within 22 miles; 3,000' over designated mountainous terrain"], a:1, r:"CNAF IFR minimum out of controlled airspace: 1,000' above the highest terrain, surface of the water, or obstacle within 22 miles of the intended line of flight; 2,000' over designated mountainous terrain. Option (c) is the FAR congested-area rule.", ref:"Ch 5-3, EO 2.166"},
    {q:"Per CNAF M-3710.7, during VFR operations, and except when necessary for takeoff and landing or when the mission requires otherwise, flights in fixed-wing aircraft shall not be conducted below:", o:["300' above the terrain or surface of the water", "500' above the terrain or surface of the water", "1,000' above the terrain or surface of the water", "1,500' above the terrain or surface of the water"], a:1, r:"500' above the terrain or surface of the water. This is the CNAF VFR floor for fixed-wing aircraft, which parallels but is stated separately from the FAR \"other than congested areas\" 500' rule.", ref:"Ch 5-3, EO 2.166"},
    {q:"What is the maximum holding airspeed for turbojet aircraft above 14,000' MSL?", o:["175 KIAS", "200 KIAS", "230 KIAS", "265 KIAS"], a:3, r:"265 KIAS. Holding airspeeds: 175 KIAS for all propeller-driven (including turboprop); turbojet below 14,000' MSL is 230 KIAS, above 14,000' MSL is 265 KIAS; helicopters 80 KIAS.", ref:"Ch 5-3, EO 2.167"},
    {q:"CNAF M-3710.7 requires that commercial carriers and aircraft of civil registry be scrupulously avoided by a margin of at least:", o:["500' vertically and/or 1,000' laterally", "500' vertically and/or 2,000' laterally", "500' vertically and/or 1 SM laterally", "1,000' vertically and/or 1 SM laterally"], a:2, r:"500' vertically and/or 1 SM laterally. Unless ordered otherwise by competent ATC authority. Under no circumstances shall aircraft be flown erratically or acrobatically in close vicinity of civil aircraft.", ref:"Ch 5-3, EO 2.170"},
    {q:"Regarding careless or reckless flying, CNAF M-3710.7 imposes a more stringent standard than the FAR. That standard is best described as:", o:["It is sufficient that the pilot be satisfied no person is actually endangered", "Flights shall be conducted so that a minimum of annoyance is experienced by persons on the ground; it is not enough that no one is actually endangered \u2014 the perception of the affected person governs", "Only maneuvers below 500' AGL over populated areas are considered careless", "The standard applies only to flight over private property"], a:1, r:"CNAF M-3710.7: \"It is not enough for the pilot to be satisfied that no person is actually endangered. Definite and particular effort shall be taken to fly in such a manner those individuals do not believe they or their property are endangered.\" What matters is not what the pilot thinks but what the affected person thinks.", ref:"Ch 5-3, EO 2.168/2.169"},
  ]
},
];
